import { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { shopProductsListData, shopSortOptions } from '../../mocks/shopProductsList';
import ShopFilterSidebar from './components/ShopFilterSidebar';
import ShopProductCard from './components/ShopProductCard';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function ShopList() {
  const [selectedCategory, setSelectedCategory] = useState('すべて');
  const [selectedBrand, setSelectedBrand] = useState('すべて');
  const [priceMin, setPriceMin] = useState('');
  const [priceMax, setPriceMax] = useState('');
  const [sortBy, setSortBy] = useState('newest');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 9;

  const filteredProducts = useMemo(() => {
    let result = [...shopProductsListData];

    if (selectedCategory !== 'すべて') {
      result = result.filter((p) => p.category === selectedCategory);
    }
    if (selectedBrand !== 'すべて') {
      result = result.filter((p) => p.brand === selectedBrand);
    }
    if (priceMin) {
      result = result.filter((p) => p.price >= Number(priceMin));
    }
    if (priceMax) {
      result = result.filter((p) => p.price <= Number(priceMax));
    }

    switch (sortBy) {
      case 'price-asc':
        result.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        result.sort((a, b) => b.price - a.price);
        break;
      case 'popular':
        result.sort((a, b) => {
          const aP = a.tags.includes('人気') ? 1 : 0;
          const bP = b.tags.includes('人気') ? 1 : 0;
          return bP - aP;
        });
        break;
      case 'rating':
        result.sort((a, b) => b.rating - a.rating);
        break;
      default:
        break;
    }

    return result;
  }, [selectedCategory, selectedBrand, priceMin, priceMax, sortBy]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const paginatedProducts = filteredProducts.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  const handleReset = () => {
    setSelectedCategory('すべて');
    setSelectedBrand('すべて');
    setPriceMin('');
    setPriceMax('');
    setCurrentPage(1);
  };

  const handleFilterChange =
    (setter: (v: string) => void) => (value: string) => {
      setter(value);
      setCurrentPage(1);
    };

  return (
    <div className="min-h-screen bg-white">
      {/* 共通ヘッダー */}
      <GlobalHeader />

      {/* ページヘッダーバナー */}
      <div className="bg-gradient-to-r from-red-600 to-orange-500 py-6 px-6">
        <div className="max-w-[1400px] mx-auto flex items-center justify-between">
          <div>
            <h1 className="text-white text-2xl font-bold flex items-center gap-3">
              <i className="ri-shopping-bag-line text-3xl"></i>
              ショッピング 商品一覧
            </h1>
            <p className="text-orange-100 text-sm mt-1">
              自動車パーツ・用品を豊富に取り揃え！お得な商品が見つかる
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className="bg-white/20 rounded-lg px-4 py-2 text-white text-center">
              <p className="text-2xl font-bold">{shopProductsListData.length}</p>
              <p className="text-xs">商品掲載中</p>
            </div>
          </div>
        </div>
      </div>

      {/* パンくずリスト */}
      <Breadcrumb items={[{ label: 'ショッピング 商品一覧' }]} />

      {/* メインコンテンツ */}
      <main className="max-w-[1400px] mx-auto px-6 pb-12">
        <div className="flex gap-6">
          {/* サイドバー */}
          <ShopFilterSidebar
            selectedCategory={selectedCategory}
            selectedBrand={selectedBrand}
            priceMin={priceMin}
            priceMax={priceMax}
            onCategoryChange={handleFilterChange(setSelectedCategory)}
            onBrandChange={handleFilterChange(setSelectedBrand)}
            onPriceMinChange={(v) => { setPriceMin(v); setCurrentPage(1); }}
            onPriceMaxChange={(v) => { setPriceMax(v); setCurrentPage(1); }}
            onReset={handleReset}
          />

          {/* 商品一覧 */}
          <div className="flex-1">
            {/* ソートバー */}
            <div className="flex items-center justify-between mb-4 bg-gray-50 border border-gray-200 rounded-lg px-4 py-3">
              <div className="flex items-center gap-3">
                <p className="text-sm text-gray-700">
                  <strong className="text-red-600">{filteredProducts.length}</strong>{' '}件の商品
                </p>
                {(selectedCategory !== 'すべて' || selectedBrand !== 'すべて' || priceMin || priceMax) && (
                  <div className="flex items-center gap-2 flex-wrap">
                    {selectedCategory !== 'すべて' && (
                      <span className="bg-red-100 text-red-800 text-xs px-2 py-1 rounded flex items-center gap-1 whitespace-nowrap">
                        {selectedCategory}
                        <button onClick={() => { setSelectedCategory('すべて'); setCurrentPage(1); }} className="hover:text-red-600 cursor-pointer">
                          <i className="ri-close-line"></i>
                        </button>
                      </span>
                    )}
                    {selectedBrand !== 'すべて' && (
                      <span className="bg-red-100 text-red-800 text-xs px-2 py-1 rounded flex items-center gap-1 whitespace-nowrap">
                        {selectedBrand}
                        <button onClick={() => { setSelectedBrand('すべて'); setCurrentPage(1); }} className="hover:text-red-600 cursor-pointer">
                          <i className="ri-close-line"></i>
                        </button>
                      </span>
                    )}
                  </div>
                )}
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-gray-500 whitespace-nowrap">並び替え：</span>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="border border-gray-300 rounded px-3 py-1.5 text-sm cursor-pointer focus:outline-none focus:border-red-500"
                >
                  {shopSortOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* 商品グリッド */}
            {paginatedProducts.length > 0 ? (
              <div className="grid grid-cols-3 gap-4 mb-8" data-product-shop>
                {paginatedProducts.map((product) => (
                  <ShopProductCard key={product.id} product={product} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-gray-50 rounded-lg">
                <i className="ri-search-line text-5xl text-gray-300 mb-4"></i>
                <p className="text-gray-500 text-lg mb-2">該当する商品が見つかりませんでした</p>
                <p className="text-gray-400 text-sm mb-4">条件を変更して再度お試しください</p>
                <button
                  onClick={handleReset}
                  className="bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-sm hover:bg-red-700 cursor-pointer whitespace-nowrap"
                >
                  条件をリセット
                </button>
              </div>
            )}

            {/* ページネーション */}
            {totalPages > 1 && (
              <div className="flex items-center justify-center gap-2">
                <button
                  onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                  disabled={currentPage === 1}
                  className={`w-9 h-9 rounded flex items-center justify-center text-sm whitespace-nowrap ${
                    currentPage === 1
                      ? 'bg-gray-100 text-gray-300 cursor-not-allowed'
                      : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100 cursor-pointer'
                  }`}
                >
                  <i className="ri-arrow-left-s-line"></i>
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    className={`w-9 h-9 rounded flex items-center justify-center text-sm cursor-pointer whitespace-nowrap ${
                      currentPage === page
                        ? 'bg-red-600 text-white font-bold'
                        : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    {page}
                  </button>
                ))}
                <button
                  onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                  disabled={currentPage === totalPages}
                  className={`w-9 h-9 rounded flex items-center justify-center text-sm whitespace-nowrap ${
                    currentPage === totalPages
                      ? 'bg-gray-100 text-gray-300 cursor-not-allowed'
                      : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100 cursor-pointer'
                  }`}
                >
                  <i className="ri-arrow-right-s-line"></i>
                </button>
              </div>
            )}

            {/* お得情報バナー */}
            <div className="mt-8 bg-gradient-to-r from-red-50 to-orange-50 border border-red-200 rounded-lg p-6">
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 bg-red-600 rounded-full flex items-center justify-center flex-shrink-0">
                  <i className="ri-gift-line text-white text-xl"></i>
                </div>
                <div>
                  <h3 className="text-base font-bold text-gray-800 mb-2">
                    AutoGarage ショッピング特典
                  </h3>
                  <div className="grid grid-cols-3 gap-4">
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-red-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">5,500円以上のお買い物で送料無料</p>
                    </div>
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-red-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">全商品ポイント還元対象</p>
                    </div>
                    <div className="flex items-start gap-2">
                      <i className="ri-check-double-line text-red-600 w-4 h-4 flex items-center justify-center mt-0.5"></i>
                      <p className="text-xs text-gray-600">14時までのご注文で当日出荷</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}
