
import { useState } from 'react';
import { shopCategories, shopBrands } from '../../../mocks/shopProductsList';

interface ShopFilterSidebarProps {
  selectedCategory: string;
  selectedBrand: string;
  priceMin: string;
  priceMax: string;
  onCategoryChange: (v: string) => void;
  onBrandChange: (v: string) => void;
  onPriceMinChange: (v: string) => void;
  onPriceMaxChange: (v: string) => void;
  onReset: () => void;
}

export default function ShopFilterSidebar({
  selectedCategory,
  selectedBrand,
  priceMin,
  priceMax,
  onCategoryChange,
  onBrandChange,
  onPriceMinChange,
  onPriceMaxChange,
  onReset,
}: ShopFilterSidebarProps) {
  const [brandExpanded, setBrandExpanded] = useState(false);
  const visibleBrands = brandExpanded ? shopBrands : shopBrands.slice(0, 10);

  return (
    <div className="w-60 flex-shrink-0">
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden sticky top-4">
        <div className="bg-red-600 text-white py-3 px-4 flex items-center justify-between">
          <span className="font-bold text-sm flex items-center gap-2">
            <i className="ri-filter-3-line"></i>
            絞り込み検索
          </span>
          <button
            onClick={onReset}
            className="text-xs underline hover:text-red-200 cursor-pointer whitespace-nowrap"
          >
            クリア
          </button>
        </div>

        <div className="p-4 space-y-5">
          {/* カテゴリ */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-folder-line text-red-600 w-4 h-4 flex items-center justify-center"></i>
              カテゴリ
            </h4>
            <div className="space-y-1">
              {shopCategories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => onCategoryChange(cat)}
                  className={`block w-full text-left text-sm py-1.5 px-3 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    selectedCategory === cat
                      ? 'bg-red-100 text-red-800 font-bold'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* ブランド */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-price-tag-line text-red-600 w-4 h-4 flex items-center justify-center"></i>
              ブランド
            </h4>
            <div className="space-y-1">
              {visibleBrands.map((br) => (
                <button
                  key={br}
                  onClick={() => onBrandChange(br)}
                  className={`block w-full text-left text-sm py-1.5 px-3 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    selectedBrand === br
                      ? 'bg-red-100 text-red-800 font-bold'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  {br}
                </button>
              ))}
              {shopBrands.length > 10 && (
                <button
                  onClick={() => setBrandExpanded(!brandExpanded)}
                  className="text-xs text-red-600 hover:underline cursor-pointer px-3 pt-1 whitespace-nowrap"
                >
                  {brandExpanded ? '閉じる' : `他${shopBrands.length - 10}件を表示`}
                </button>
              )}
            </div>
          </div>

          {/* 価格帯 */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-money-yen-circle-line text-red-600 w-4 h-4 flex items-center justify-center"></i>
              価格帯
            </h4>
            <div className="flex items-center gap-2">
              <input
                type="number"
                placeholder="下限"
                value={priceMin}
                onChange={(e) => onPriceMinChange(e.target.value)}
                className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:border-red-500 cursor-text"
              />
              <span className="text-gray-400 text-xs">〜</span>
              <input
                type="number"
                placeholder="上限"
                value={priceMax}
                onChange={(e) => onPriceMaxChange(e.target.value)}
                className="w-full border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:border-red-500 cursor-text"
              />
            </div>
          </div>

          {/* 送料 */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-truck-line text-red-600 w-4 h-4 flex items-center justify-center"></i>
              送料
            </h4>
            <div className="space-y-1">
              <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer px-3 py-1.5 hover:bg-gray-100 rounded">
                <input type="checkbox" className="accent-red-600 cursor-pointer" />
                送料無料のみ
              </label>
            </div>
          </div>

          {/* タグ */}
          <div>
            <h4 className="text-sm font-bold text-gray-800 mb-2 flex items-center gap-1">
              <i className="ri-bookmark-line text-red-600 w-4 h-4 flex items-center justify-center"></i>
              タグ
            </h4>
            <div className="flex flex-wrap gap-1.5 px-1">
              {['NEW', 'SALE', '人気'].map((tag) => (
                <span
                  key={tag}
                  className={`text-xs px-2.5 py-1 rounded cursor-pointer transition-colors whitespace-nowrap ${
                    tag === 'NEW'
                      ? 'bg-red-100 text-red-600 hover:bg-red-200'
                      : tag === 'SALE'
                      ? 'bg-orange-100 text-orange-600 hover:bg-orange-200'
                      : 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200'
                  }`}
                >
                  {tag}
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
